package org.example.jobpostingcrawler.structurediscovery;

import java.util.Collection;
import java.util.regex.Pattern;

/**
 * Class names generated by CSS-in-JS libraries. They change on every deploy of the site, so XPaths must not rely
 * on them and the LLM does not need to see them.
 * <pre>
 *  styled-components (VietnamWorks): class="sc-d1ecfd52-0 bSkXqn"
 *  emotion / styled-jsx:             class="css-1x2y3z4 jsx-f6f85871d7bde676"
 * </pre>
 */
public final class GeneratedClasses {

    /** Component id of the library: sc-d1ecfd52-0, css-1x2y3z4, jsx-f6f85871d7bde676. */
    private static final Pattern LIBRARY_CLASS = Pattern.compile(
            "^(css|sc|jsx|emotion|styled|tw)-[a-z0-9_-]{4,}$", Pattern.CASE_INSENSITIVE);
    /** Random hash next to it: bSkXqn, kzLqgg, hmvhgA (letters only, mixed case). */
    private static final Pattern STYLED_HASH = Pattern.compile("^(?=.*[a-z])(?=.*[A-Z])[A-Za-z]{5,8}$");

    private GeneratedClasses() {
    }

    /**
     * @param classes all class names of the element: a mixed-case word like "jobTitle" is only treated as a hash
     *                when the element also carries a CSS-in-JS library class
     */
    public static boolean isGenerated(String c, Collection<String> classes) {
        if (LIBRARY_CLASS.matcher(c).matches()) {
            return true;
        }
        return STYLED_HASH.matcher(c).matches()
                && classes.stream().anyMatch(other -> LIBRARY_CLASS.matcher(other).matches());
    }
}
